from ub import *
UNIT = mkunit("u158",
 ["memilih kata atau frasa yang **melengkapi kalimat** (Structure)",
  "mengenali **subjek, kata kerja, dan klausa** yang hilang",
  "memakai pola **paralel, inversi, dan klausa relatif**",
  "menyelesaikan satu soal dalam sekitar **35 detik**"],
 [intro("Bagian **Structure** menguji apakah kamu bisa melengkapi kalimat dengan bentuk yang tepat. Soalnya sangat berpola: kalimat harus punya **subjek**, **kata kerja berimbuhan**, dan susunan yang benar. Cari dulu apa yang **hilang** dari kalimat itu."),
  gram("1. Daftar periksa kalimat lengkap",
   table=[["Periksa", "Pertanyaan", "Contoh"],
          ["Subjek", "Apakah ada subjek?", "[[___ have shown ...]] → [[Studies]]"],
          ["Kata kerja", "Apakah ada kata kerja bertense?", "[[The report ___ last week]]"],
          ["Klausa", "Apakah klausa anak punya penghubung?", "[[Although ..., ...]]"],
          ["Paralel", "Apakah bentuk dalam daftar sama?", "[[reading, writing, and speaking]]"],
          ["Inversi", "Not only, hardly, rarely → balik urutan", "[[Not only did she pass]]"],
          ["Subjunctive", "essential/suggest that + kata kerja dasar", "[[It is essential that he submit ...]]"]]),
  warn("Dua kata kerja berbentuk tense tidak boleh berdiri bersama", text="Jangan pilih opsi yang menghasilkan dua kata kerja bertense tanpa penghubung. Gunakan bentuk reduksi (written, living) atau klausa relatif (that was written)."),
  tip("Coret dulu yang jelas salah", text="Coret opsi yang menghasilkan kalimat tanpa subjek atau dengan dua kata kerja bertense. Biasanya tersisa dua opsi."),
  summary(["Kalimat butuh subjek dan kata kerja bertense.", "Klausa anak butuh penghubung.", "Paralel: bentuk sama dalam daftar.", "Not only/hardly/rarely → inversi.", "Essential that → kata kerja dasar."])],
 [], [])
S = [
 ("The study of fossils, ___ paleontology, shows how life changed.", "known as", "is known", "knowing as", "it is known as", "Frasa reduksi: known as."),
 ("___ have shown that sleep improves memory.", "Studies", "Studying", "Studied", "A study", "Subjek jamak."),
 ("The Amazon is ___ than any other river in the world.", "larger", "the largest", "large", "more large", "Than → komparatif."),
 ("Not only ___ the exam, but she also won a scholarship.", "did she pass", "she passed", "passed she", "she did pass", "Inversi setelah Not only."),
 ("Hardly had the lecture begun ___ the lights went out.", "when", "than", "that", "then", "Hardly ... when."),
 ("It is essential that every student ___ the form by Friday.", "submit", "submits", "submitted", "will submit", "Subjunctive."),
 ("The professor, ___ research focuses on climate, spoke at the conference.", "whose", "who", "which", "his", "Milik → whose."),
 ("___ the rain, the match continued.", "Despite", "Although", "Because", "However", "Despite + kata benda."),
 ("She suggested ___ to the museum on Saturday.", "going", "to go", "go", "went", "Suggest + V-ing."),
 ("The more you practise, ___ you become.", "the better", "better", "the best", "more better", "The + komparatif."),
 ("Scientists have discovered a new species ___ in the deep sea.", "living", "lives", "lived", "to live", "Frasa partisip."),
 ("The report ___ by the committee last week was very detailed.", "written", "writing", "wrote", "was written", "Reduksi relatif: written."),
 ("If I ___ more time, I would travel around the world.", "had", "have", "has", "would have", "If + past."),
 ("___ the city is large, it has no subway.", "Although", "Despite", "Because of", "In spite", "Although + klausa."),
 ("Neither the teachers nor the principal ___ aware of the change.", "was", "were", "are", "have been", "Subjek terdekat tunggal."),
 ("The number of tourists ___ grown steadily.", "has", "have", "are", "is", "The number of → tunggal."),
 ("It was in 1969 ___ humans first walked on the moon.", "that", "what", "who", "where", "Cleft sentence."),
 ("Rarely ___ such a beautiful sunset.", "have I seen", "I have seen", "I seen", "seen I", "Inversi."),
 ("She is one of the scientists ___ the prize.", "who won", "who has won", "whom won", "which won", "Orang: who + jamak."),
 ("He asked me ___ I had finished the report.", "whether", "that", "what", "which", "Ask + whether."),
 ("Water boils at 100 degrees Celsius ___ sea level.", "at", "in", "on", "by", "At sea level."),
 ("The scientist, along with her assistants, ___ the experiment.", "is conducting", "are conducting", "conduct", "have conducted", "Subjek: the scientist."),
 ("By the time we arrived, the film ___.", "had started", "started", "has started", "starts", "Past perfect."),
 ("___ was found in the cave surprised the researchers.", "What", "That", "Which", "Who", "What sebagai subjek."),
 ("A large amount of ___ is needed for this project.", "money", "moneys", "many money", "monies", "Uncountable."),
 ("Having finished the work, ___.", "the workers went home", "went home the workers", "home the workers went", "the workers going home", "Subjek = pelaku Having finished."),
 ("Researchers have found that people ___ outdoors tend to feel happier.", "who exercise", "exercising are", "they exercise", "exercise", "Klausa relatif."),
 ("The committee meets ___ month.", "every", "each of", "all", "most", "Every + tunggal."),
]
allq = mk([(f'Structure. {q}', c, a, b, d, e) for q, c, a, b, d, e in S])
UNIT["practice"] = allq[:22]
UNIT["quiz"] = allq[22:] + allq[:3]
